procedure @@proc@@ is
  cursor c_open is
    select id from @@tab@@ where @@col@@ is null;
begin
  for r in c_open loop
    insert into @@tab2@@ (id) values (r.id); -- @expect
  end loop;
  dbms_output.put_line('copied');
end @@proc@@;

procedure @@proc@@(p_min in number) is
  cursor c_rows is select id, @@col@@ from @@tab@@;
  l_id number;
  l_val number;
begin
  open c_rows;
  loop
    fetch c_rows into l_id, l_val;
    exit when c_rows%notfound;
    if l_val > p_min then
      update @@tab2@@ set @@col2@@ = l_val where id = l_id; -- @expect
    end if;
  end loop;
  close c_rows;
end @@proc@@;

procedure @@proc@@(p_days in number) is
  cursor c_old(p_age number) is
    select id from @@tab@@ where age_days > p_age;
begin
  for r in c_old(p_days) loop
    delete from @@tab2@@ -- @expect
     where parent_id = r.id;
  end loop;
end @@proc@@;

