procedure @@proc@@ is
  type t_ids is table of number index by pls_integer;
  l_ids t_ids;
begin
  select id bulk collect into l_ids from @@tab@@ where @@col@@ is null;
  forall i in 1 .. l_ids.count
    delete from @@tab2@@ where parent_id = l_ids(i);
end @@proc@@;

procedure @@proc@@(p_n in number) is
begin
  for i in 1 .. p_n loop
    update @@tab@@
       set @@col@@ = i
     where id = i;
  end loop;
end @@proc@@;

procedure @@proc@@ is
  l_total number := 0;
begin
  for r in (select id, @@col@@ from @@tab@@) loop
    l_total := l_total + r.@@col@@;
  end loop;
  update @@tab2@@ set @@col2@@ = l_total;
end @@proc@@;

procedure @@proc@@ is
  cursor c_all is select id, @@col@@ from @@tab@@;
  l_seen number := 0;
begin
  for r in c_all loop
    dbms_output.put_line(r.id || ' ' || r.@@col@@);
    l_seen := l_seen + 1;
  end loop;
  dbms_output.put_line('rows seen: ' || l_seen);
end @@proc@@;

